import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from "remotion";
import { BRAND, BRAND_FONT_FACE_CSS } from "../../theme";

export const fps = 30;
export const durationInFrames = 120;

const NAME = "Filip Kadlec";
const ROLE = "Developer Advocate · Apify";
const ACCENT = BRAND.colors.pink;

export default function LowerThird() {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  const inProgress = spring({ frame, fps: vfps, delay: 0, config: { damping: 200 } });
  const outStart = durationInFrames - 18;
  const outProgress = spring({
    frame: Math.max(0, frame - outStart),
    fps: vfps,
    config: { damping: 200 },
  });

  const x = interpolate(inProgress, [0, 1], [-width * 0.4, 0]) +
    interpolate(outProgress, [0, 1], [0, -width * 0.4]);

  const opacity = Math.min(inProgress, 1 - outProgress);

  const padX = width * 0.04;
  const padY = height * 0.03;

  return (
    <>
      <style>{BRAND_FONT_FACE_CSS}</style>
      <AbsoluteFill style={{ background: "transparent" }}>
        <div
          style={{
            position: "absolute",
            left: padX,
            bottom: padY,
            display: "flex",
            alignItems: "stretch",
            transform: `translateX(${x}px)`,
            opacity,
            boxShadow: `0 ${height * 0.01}px ${height * 0.03}px rgba(0,0,0,0.4)`,
            borderRadius: height * 0.008,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              width: height * 0.012,
              background: ACCENT,
            }}
          />
          <div
            style={{
              padding: `${height * 0.018}px ${width * 0.022}px`,
              background: BRAND.colors.bg,
              display: "flex",
              flexDirection: "column",
              gap: height * 0.005,
              backdropFilter: "blur(20px)",
            }}
          >
            <div
              style={{
                fontFamily: BRAND.fonts.marketing,
                fontWeight: 700,
                fontSize: height * 0.045,
                color: BRAND.colors.text,
                lineHeight: 1,
                letterSpacing: "-0.01em",
              }}
            >
              {NAME}
            </div>
            <div
              style={{
                fontFamily: BRAND.fonts.primary,
                fontWeight: 500,
                fontSize: height * 0.018,
                color: BRAND.colors.textMuted,
                letterSpacing: "0.02em",
              }}
            >
              {ROLE}
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </>
  );
}
